create table public.lunch_ui_texts (
 text_key text primary key check(length(text_key) between 1 and 500),
 de_text text not null check(length(de_text) between 1 and 4000),
 en_text text not null check(length(en_text) between 1 and 4000),
 updated_at timestamptz not null default now()
);
alter table public.lunch_ui_texts enable row level security;
grant select on public.lunch_ui_texts to anon, authenticated;
grant insert, update on public.lunch_ui_texts to authenticated;
grant select, insert, update, delete on public.lunch_ui_texts to service_role;
create policy "public reads interface texts" on public.lunch_ui_texts for select to anon, authenticated using (true);
create policy "lunch admins insert interface texts" on public.lunch_ui_texts for insert to authenticated with check ((select private.is_lunch_admin()));
create policy "lunch admins update interface texts" on public.lunch_ui_texts for update to authenticated using ((select private.is_lunch_admin())) with check ((select private.is_lunch_admin()));
create function private.touch_lunch_ui_text_timestamp() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
create trigger lunch_ui_text_timestamp before update on public.lunch_ui_texts for each row execute function private.touch_lunch_ui_text_timestamp();

